#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_print_number_positive_num_digits_to_print_valid(void) {
    // Setup: number array with digits, N > 0, number != NULL
    // Path conditions: (number == NULL || N == 0) is FALSE
    //                  num_digits_to_print >= 0 (since path goes to second else-if)
    //                  num_digits_to_print <= start_pos (since path goes to true branch)
    // We need start_pos after skipping leading zeros.
    // Let's create number representing 12345 with N=5, little-endian: [5,4,3,2,1]
    // start_pos will be 4 (since no leading zeros).
    // Choose num_digits_to_print = 3 (<= start_pos).
    // Expected: prints digits from start_pos down to end_pos = start_pos - num_digits_to_print + 1 = 4 - 3 + 1 = 2
    // So prints indices 4,3,2 -> digits '1','2','3' -> output "123
"

    uint8_t N = 5;
    uint8_t number[] = {5, 4, 3, 2, 1}; // 12345 in little-endian
    int8_t num_digits_to_print = 3;

    // Use helper to capture stdout and assert output
    stdout_capture_t *cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    int result = print_number(number, N, num_digits_to_print);

    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, result); // Should return success
    TEST_ASSERT_EQUAL_STRING("123
", output);

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_print_number_positive_num_digits_to_print_valid);
    return UNITY_END();
}

